SELECT p.id, t.name FROM (VALUES
 ('careflow-appointment-api','Java'),('careflow-appointment-api','Spring Boot'),('careflow-appointment-api','PostgreSQL'),('careflow-appointment-api','JUnit'),
 ('learnspace-student-portal','React'),('learnspace-student-portal','TypeScript'),('learnspace-student-portal','CSS'),('learnspace-student-portal','Jest'),
 ('spendwise-expense-service','Python'),('spendwise-expense-service','Django'),('spendwise-expense-service','PostgreSQL'),('spendwise-expense-service','Git'),
 ('stockpilot-inventory-service','Java'),('stockpilot-inventory-service','Spring Boot'),('stockpilot-inventory-service','PostgreSQL'),('stockpilot-inventory-service','Redis')
) AS t(slug,name) JOIN projects p ON p.slug=t.slug ON CONFLICT (project_id, technology_name) DO NOTHING;
